// Fonction pour obtenir une traduction
function getIdeogramTranslation(key, lang) {
    if (ideogramTranslations[lang] && ideogramTranslations[lang][key]) {
        return ideogramTranslations[lang][key];
    }
    // Fallback à l'anglais
    if (ideogramTranslations.en && ideogramTranslations.en[key]) {
        return ideogramTranslations.en[key];
    }
    return null;
}

// Appliquer les traductions ideogram
function applyIdeogramTranslations(lang) {
    console.log('🔥 Applying ideogram translations for:', lang);

    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');

        // Seulement pour les clés ideogram
        if (key && (key.startsWith('review.ideogram.') || key.startsWith('review.common.'))) {
            const translation = getIdeogramTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });

    console.log(`✅ Applied ${count} ideogram translations`);
}

// Auto-appliquer quand la langue change
document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyIdeogramTranslations(lang), 200);
});

// Appliquer au chargement
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyIdeogramTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyIdeogramTranslations(currentLang);
}

console.log('✅ ideogram i18n loaded');
